"""Fixed equal probability blend of model10, model12, and model15 CoAtNet.
Checkpoint and geometry credit: Johnathan Wagner / Dread Development; public CC0 datasets.
"""
import json
import os
from pathlib import Path
import subprocess
import sys
import time
import numpy as np
import pandas as pd

MODEL12_CODE = '"""CoAtNet inference compatible with Dread Development\'s public knee checkpoint.\n\nArchitecture and geometry credit: Johnathan Wagner / Dread Development.\nSource: https://www.kaggle.com/code/dreaddevelopment/knee-mri-twelve-findings-from-a-single-model\nModel12: max-span checkpoint with documented 2%-98% sampling.\nThis implementation uses only images and public series metadata.\n"""\nimport gc\nimport json\nimport os\nimport time\nfrom pathlib import Path\n\nos.environ[\'HF_HUB_OFFLINE\'] = \'1\'\nos.environ[\'TRANSFORMERS_OFFLINE\'] = \'1\'\n\nimport cv2\nimport numpy as np\nimport pandas as pd\nimport pydicom\nimport timm\nimport torch\nfrom pydicom.pixels import apply_modality_lut\nfrom torch import nn\nfrom torch.nn import functional as F\n\nUID = \'StudyInstanceUID\'\nSLOTS = [(\'Sagittal\', 1, 18), (\'Sagittal\', 0, 14), (\'Coronal\', 1, 12),\n         (\'Coronal\', 0, 8), (\'Axial\', -1, 12)]\nLABELS = [\'ACL\', \'MCL\', \'Medial Meniscus\', \'Lateral Meniscus\', \'Medial OA\',\n          \'Lateral OA\', \'PF OA\', \'Effusion\', \'Synovitis\', "Baker\'s", \'Contusion\', \'Fracture\']\n\n\nclass Classifier(nn.Module):\n    def __init__(self, arch):\n        super().__init__()\n        self.backbone = timm.create_model(arch, pretrained=False, num_classes=0,\n                                          in_chans=3, global_pool=\'avg\')\n        dim = self.backbone.num_features\n        self.norm = nn.LayerNorm(dim)\n        self.att = nn.Sequential(nn.Linear(dim, 256), nn.Tanh(), nn.Dropout(.2), nn.Linear(256, 12))\n        self.clsW = nn.Parameter(torch.zeros(12, dim))\n        self.clsb = nn.Parameter(torch.zeros(12))\n\n    def predict_features(self, features):\n        features = self.norm(features)\n        attention = self.att(features).softmax(dim=1)\n        pooled = torch.einsum(\'bkn,bkf->bnf\', attention, features)\n        return (pooled * self.clsW).sum(-1) + self.clsb\n\n\ndef ordered_files(directory):\n    records = []\n    for path in directory.glob(\'*.dcm\'):\n        header = pydicom.dcmread(path, stop_before_pixels=True)\n        orientation = getattr(header, \'ImageOrientationPatient\', None)\n        position = getattr(header, \'ImagePositionPatient\', None)\n        if orientation is not None and position is not None and len(orientation) == 6:\n            normal = np.cross(np.asarray(orientation[:3], float), np.asarray(orientation[3:], float))\n            order = float(np.dot(np.asarray(position, float), normal))\n        else:\n            order = float(getattr(header, \'InstanceNumber\', 0) or 0)\n        spacing = getattr(header, \'PixelSpacing\', None)\n        records.append((order, path, float(spacing[0]) if spacing is not None else .5))\n    records.sort(key=lambda x: x[0])\n    return records\n\n\ndef read_study(uid, rows, series_root):\n    volume = np.zeros((64, 336, 336), dtype=np.uint8)\n    used, offset, failed = set(), 0, 0\n    for plane, fluid, count in SLOTS:\n        candidates = [r for r in rows if r[\'Anatomical_Plane\'] == plane and r[\'SeriesInstanceUID\'] not in used]\n        preferred = [r for r in candidates if int(r[\'Fluid_Sensitive\']) == fluid] if fluid in (0,1) else []\n        chosen = (preferred or candidates)\n        if not chosen:\n            offset += count\n            continue\n        row = chosen[0]; used.add(row[\'SeriesInstanceUID\'])\n        records = ordered_files(series_root / uid / row[\'SeriesInstanceUID\'])\n        if not records:\n            raise FileNotFoundError(\'Declared series has no DICOM files\')\n        n = len(records); lo = int(n * .02); hi = max(lo, int(n * .98)-1)\n        indices = np.rint(np.linspace(lo, hi, count)).astype(int) if n > 1 else np.zeros(count, dtype=int)\n        selected = []\n        for i in indices:\n            _, path, spacing = records[min(i, n-1)]\n            try:\n                ds = pydicom.dcmread(path)\n                array = apply_modality_lut(ds.pixel_array, ds).astype(np.float32)\n                if array.ndim != 2 or not np.isfinite(array).all():\n                    raise ValueError(\'Invalid decoded MRI pixels\')\n                if str(getattr(ds, \'PhotometricInterpretation\', \'\')) == \'MONOCHROME1\':\n                    array = array.max() - array\n                selected.append((array, spacing))\n            except (ValueError, RuntimeError, NotImplementedError):\n                selected.append((None, spacing)); failed += 1\n        valid = [a for a, _ in selected if a is not None]\n        if not valid:\n            raise ValueError(\'No decodable slices in selected series\')\n        low, high = np.percentile(np.concatenate([a.ravel() for a in valid]), [2, 98])\n        median_spacing = float(np.median([r[2] for r in records]))\n        for array, spacing in selected:\n            if array is not None:\n                array = np.clip((array-low)/(high-low+1e-6), 0, 1)\n                spacing = spacing if spacing > 0 else median_spacing\n                h, w = array.shape\n                size = min(int(round(140/max(spacing, 1e-3))), h, w)\n                y, x = (h-size)//2, (w-size)//2\n                crop = cv2.resize(array[y:y+size, x:x+size], (336,336), interpolation=cv2.INTER_AREA)\n                volume[offset] = (crop * 255).astype(np.uint8)\n            offset += 1\n    mask = volume.reshape(64,-1).sum(1) > 0\n    if not mask.any():\n        raise ValueError(\'Study has no usable images\')\n    return volume, mask, failed\n\n\ndef windows(volume, mask, size):\n    valid = np.flatnonzero(mask)\n    if len(valid) < 3:\n        valid = np.arange(3)\n    lo, hi = int(valid.min()), int(valid.max())\n    centers = list(range(lo+1, hi)) or [max(1, min((lo+hi)//2, len(volume)-2))]\n    indices = np.arange(len(centers))\n    slices = np.stack([volume[centers[i]-1:centers[i]+2] for i in indices]).astype(np.float32) / 255\n    images = F.interpolate(torch.from_numpy(slices), size=(size,size), mode=\'bilinear\', align_corners=False)\n    return (images - torch.tensor([.485,.456,.406]).view(1,3,1,1)) / torch.tensor([.229,.224,.225]).view(1,3,1,1)\n\n\n@torch.inference_mode()\ndef predict(model, images, device):\n    encoded = []\n    with torch.autocast(device.type, enabled=device.type==\'cuda\', dtype=torch.float16):\n        for batch in images.split(12):\n            encoded.append(model.backbone(batch.to(device)))\n        logits = model.predict_features(torch.cat(encoded).unsqueeze(0))\n    probabilities = logits.float().sigmoid().cpu().numpy()[0]\n    if not np.isfinite(probabilities).all():\n        raise ValueError(\'Nonfinite model predictions\')\n    return probabilities\n\n\ndef main():\n    started = time.time();torch.set_num_threads(4)\n    torch.backends.cudnn.benchmark = True\n    device = torch.device(\'cuda\' if torch.cuda.is_available() else \'cpu\')\n    print(\'Device:\', device, \'torch:\', torch.__version__, \'timm:\', timm.__version__, flush=True)\n    if device.type == \'cuda\':print(\'GPU:\', torch.cuda.get_device_name(), flush=True)\n    inputs = Path(\'/kaggle/input\')\n    roots = [p for p in [inputs/\'competitions/rsna-knee-abnormality-detection\', inputs/\'rsna-knee-abnormality-detection\']\n             if (p/\'test.csv\').exists()]\n    assert len(roots)==1\n    root = roots[0]\n    filename = \'raptor_ft_coatnet_v5_full_swa.pt\'\n    candidates = [inputs/\'raptor-knee-maxspan\'/filename]\n    candidates += list(inputs.glob(\'datasets/dreaddevelopment/raptor-knee-maxspan/\'+filename))\n    candidates += list(inputs.glob(\'datasets/dreaddevelopment/raptor-knee-maxspan/*/\'+filename))\n    files = [p for p in candidates if p.is_file()]\n    assert len(files)==1, files\n    ck = torch.load(files[0], map_location=\'cpu\', weights_only=True)\n    print(\'Checkpoint metadata:\', {k: v for k, v in ck.items() if isinstance(v, (str, int, float, bool))}, flush=True)\n    assert list(ck.get(\'lab\', LABELS)) == LABELS\n    model = Classifier(ck[\'arch\']);model.load_state_dict(ck[\'model\'], strict=True)\n    size = int(ck[\'res\']);del ck;gc.collect()\n    model = model.to(device).eval()\n    test = pd.read_csv(root/\'test.csv\');series = pd.read_csv(root/\'test_series.csv\')\n    sample = pd.read_csv(root/\'sample_submission.csv\')\n    assert test[UID].is_unique and sample[UID].is_unique\n    groups = {uid: frame.to_dict(\'records\') for uid,frame in series.groupby(UID)}\n    result = []\n    for i, uid in enumerate(test[UID]):\n        volume, mask, failed = read_study(uid, groups[uid], root/\'test_series\')\n        result.append(predict(model, windows(volume, mask, size), device))\n        if failed:print(json.dumps({\'study\':i,\'failed_slices\':failed}),flush=True)\n        if i % 50 == 0 or i+1 == len(test):print(\'Predicted\',i+1,\'/\',len(test),\'seconds\',round(time.time()-started,1),flush=True)\n    frame = pd.DataFrame(result, columns=LABELS);frame.insert(0,UID,test[UID].to_numpy())\n    submission = sample[[UID]].merge(frame,on=UID,validate=\'one_to_one\')[sample.columns]\n    assert len(submission)==len(test) and np.isfinite(submission[LABELS]).all().all()\n    submission.to_csv(\'/kaggle/working/submission.csv\',index=False)\n    print(\'Wrote submission.csv; seconds:\',round(time.time()-started,1),flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n'
MODEL15_CODE = '"""CoAtNet inference compatible with Dread Development\'s public knee checkpoint.\n\nArchitecture and geometry credit: Johnathan Wagner / Dread Development.\nSource: https://www.kaggle.com/code/dreaddevelopment/knee-mri-twelve-findings-from-a-single-model\nModel15: native384 dense checkpoint with documented 2%-98% sampling.\nThis implementation uses only images and public series metadata.\n"""\nimport gc\nimport json\nimport os\nimport time\nfrom pathlib import Path\n\nos.environ[\'HF_HUB_OFFLINE\'] = \'1\'\nos.environ[\'TRANSFORMERS_OFFLINE\'] = \'1\'\n\nimport cv2\nimport numpy as np\nimport pandas as pd\nimport pydicom\nimport timm\nimport torch\nfrom pydicom.pixels import apply_modality_lut\nfrom torch import nn\nfrom torch.nn import functional as F\n\nUID = \'StudyInstanceUID\'\nSLOTS = [(\'Sagittal\', 1, 18), (\'Sagittal\', 0, 14), (\'Coronal\', 1, 12),\n         (\'Coronal\', 0, 8), (\'Axial\', -1, 12)]\nLABELS = [\'ACL\', \'MCL\', \'Medial Meniscus\', \'Lateral Meniscus\', \'Medial OA\',\n          \'Lateral OA\', \'PF OA\', \'Effusion\', \'Synovitis\', "Baker\'s", \'Contusion\', \'Fracture\']\n\n\nclass Classifier(nn.Module):\n    def __init__(self, arch):\n        super().__init__()\n        self.backbone = timm.create_model(arch, pretrained=False, num_classes=0,\n                                          in_chans=3, global_pool=\'avg\')\n        dim = self.backbone.num_features\n        self.norm = nn.LayerNorm(dim)\n        self.att = nn.Sequential(nn.Linear(dim, 256), nn.Tanh(), nn.Dropout(.2), nn.Linear(256, 12))\n        self.clsW = nn.Parameter(torch.zeros(12, dim))\n        self.clsb = nn.Parameter(torch.zeros(12))\n\n    def predict_features(self, features):\n        features = self.norm(features)\n        attention = self.att(features).softmax(dim=1)\n        pooled = torch.einsum(\'bkn,bkf->bnf\', attention, features)\n        return (pooled * self.clsW).sum(-1) + self.clsb\n\n\ndef ordered_files(directory):\n    records = []\n    for path in directory.glob(\'*.dcm\'):\n        header = pydicom.dcmread(path, stop_before_pixels=True)\n        orientation = getattr(header, \'ImageOrientationPatient\', None)\n        position = getattr(header, \'ImagePositionPatient\', None)\n        if orientation is not None and position is not None and len(orientation) == 6:\n            normal = np.cross(np.asarray(orientation[:3], float), np.asarray(orientation[3:], float))\n            order = float(np.dot(np.asarray(position, float), normal))\n        else:\n            order = float(getattr(header, \'InstanceNumber\', 0) or 0)\n        spacing = getattr(header, \'PixelSpacing\', None)\n        records.append((order, path, float(spacing[0]) if spacing is not None else .5))\n    records.sort(key=lambda x: x[0])\n    return records\n\n\ndef read_study(uid, rows, series_root):\n    volume = np.zeros((64, 384, 384), dtype=np.uint8)\n    used, offset, failed = set(), 0, 0\n    for plane, fluid, count in SLOTS:\n        candidates = [r for r in rows if r[\'Anatomical_Plane\'] == plane and r[\'SeriesInstanceUID\'] not in used]\n        preferred = [r for r in candidates if int(r[\'Fluid_Sensitive\']) == fluid] if fluid in (0,1) else []\n        chosen = (preferred or candidates)\n        if not chosen:\n            offset += count\n            continue\n        row = chosen[0]; used.add(row[\'SeriesInstanceUID\'])\n        records = ordered_files(series_root / uid / row[\'SeriesInstanceUID\'])\n        if not records:\n            raise FileNotFoundError(\'Declared series has no DICOM files\')\n        n = len(records); lo = int(n * .02); hi = max(lo, int(n * .98)-1)\n        indices = np.rint(np.linspace(lo, hi, count)).astype(int) if n > 1 else np.zeros(count, dtype=int)\n        selected = []\n        for i in indices:\n            _, path, spacing = records[min(i, n-1)]\n            try:\n                ds = pydicom.dcmread(path)\n                array = apply_modality_lut(ds.pixel_array, ds).astype(np.float32)\n                if array.ndim != 2 or not np.isfinite(array).all():\n                    raise ValueError(\'Invalid decoded MRI pixels\')\n                if str(getattr(ds, \'PhotometricInterpretation\', \'\')) == \'MONOCHROME1\':\n                    array = array.max() - array\n                selected.append((array, spacing))\n            except (ValueError, RuntimeError, NotImplementedError):\n                selected.append((None, spacing)); failed += 1\n        valid = [a for a, _ in selected if a is not None]\n        if not valid:\n            raise ValueError(\'No decodable slices in selected series\')\n        low, high = np.percentile(np.concatenate([a.ravel() for a in valid]), [2, 98])\n        median_spacing = float(np.median([r[2] for r in records]))\n        for array, spacing in selected:\n            if array is not None:\n                array = np.clip((array-low)/(high-low+1e-6), 0, 1)\n                spacing = spacing if spacing > 0 else median_spacing\n                h, w = array.shape\n                size = min(int(round(140/max(spacing, 1e-3))), h, w)\n                y, x = (h-size)//2, (w-size)//2\n                crop = cv2.resize(array[y:y+size, x:x+size], (384,384), interpolation=cv2.INTER_AREA)\n                volume[offset] = (crop * 255).astype(np.uint8)\n            offset += 1\n    mask = volume.reshape(64,-1).sum(1) > 0\n    if not mask.any():\n        raise ValueError(\'Study has no usable images\')\n    return volume, mask, failed\n\n\ndef windows(volume, mask, size):\n    valid = np.flatnonzero(mask)\n    if len(valid) < 3:\n        valid = np.arange(3)\n    lo, hi = int(valid.min()), int(valid.max())\n    centers = list(range(lo+1, hi)) or [max(1, min((lo+hi)//2, len(volume)-2))]\n    indices = np.arange(len(centers))\n    slices = np.stack([volume[centers[i]-1:centers[i]+2] for i in indices]).astype(np.float32) / 255\n    images = F.interpolate(torch.from_numpy(slices), size=(size,size), mode=\'bilinear\', align_corners=False)\n    return (images - torch.tensor([.485,.456,.406]).view(1,3,1,1)) / torch.tensor([.229,.224,.225]).view(1,3,1,1)\n\n\n@torch.inference_mode()\ndef predict(model, images, device):\n    encoded = []\n    with torch.autocast(device.type, enabled=device.type==\'cuda\', dtype=torch.float16):\n        for batch in images.split(12):\n            encoded.append(model.backbone(batch.to(device)))\n        logits = model.predict_features(torch.cat(encoded).unsqueeze(0))\n    probabilities = logits.float().sigmoid().cpu().numpy()[0]\n    if not np.isfinite(probabilities).all():\n        raise ValueError(\'Nonfinite model predictions\')\n    return probabilities\n\n\ndef main():\n    started = time.time();torch.set_num_threads(4)\n    torch.backends.cudnn.benchmark = True\n    device = torch.device(\'cuda\' if torch.cuda.is_available() else \'cpu\')\n    print(\'Device:\', device, \'torch:\', torch.__version__, \'timm:\', timm.__version__, flush=True)\n    if device.type == \'cuda\':print(\'GPU:\', torch.cuda.get_device_name(), flush=True)\n    inputs = Path(\'/kaggle/input\')\n    roots = [p for p in [inputs/\'competitions/rsna-knee-abnormality-detection\', inputs/\'rsna-knee-abnormality-detection\']\n             if (p/\'test.csv\').exists()]\n    assert len(roots)==1\n    root = roots[0]\n    filename = \'raptor_ft_coatnet_v10_full.pt\'\n    candidates = [inputs/\'raptor-knee-native384dense\'/filename]\n    candidates += list(inputs.glob(\'datasets/dreaddevelopment/raptor-knee-native384dense/\'+filename))\n    candidates += list(inputs.glob(\'datasets/dreaddevelopment/raptor-knee-native384dense/*/\'+filename))\n    files = [p for p in candidates if p.is_file()]\n    assert len(files)==1, files\n    ck = torch.load(files[0], map_location=\'cpu\', weights_only=True)\n    print(\'Checkpoint metadata:\', {k: v for k, v in ck.items() if isinstance(v, (str, int, float, bool))}, flush=True)\n    assert list(ck.get(\'lab\', LABELS)) == LABELS\n    model = Classifier(ck[\'arch\']);model.load_state_dict(ck[\'model\'], strict=True)\n    size = int(ck[\'res\']);del ck;gc.collect()\n    model = model.to(device).eval()\n    test = pd.read_csv(root/\'test.csv\');series = pd.read_csv(root/\'test_series.csv\')\n    sample = pd.read_csv(root/\'sample_submission.csv\')\n    assert test[UID].is_unique and sample[UID].is_unique\n    groups = {uid: frame.to_dict(\'records\') for uid,frame in series.groupby(UID)}\n    result = []\n    for i, uid in enumerate(test[UID]):\n        volume, mask, failed = read_study(uid, groups[uid], root/\'test_series\')\n        result.append(predict(model, windows(volume, mask, size), device))\n        if failed:print(json.dumps({\'study\':i,\'failed_slices\':failed}),flush=True)\n        if i % 50 == 0 or i+1 == len(test):print(\'Predicted\',i+1,\'/\',len(test),\'seconds\',round(time.time()-started,1),flush=True)\n    frame = pd.DataFrame(result, columns=LABELS);frame.insert(0,UID,test[UID].to_numpy())\n    submission = sample[[UID]].merge(frame,on=UID,validate=\'one_to_one\')[sample.columns]\n    assert len(submission)==len(test) and np.isfinite(submission[LABELS]).all().all()\n    submission.to_csv(\'/kaggle/working/submission.csv\',index=False)\n    print(\'Wrote submission.csv; seconds:\',round(time.time()-started,1),flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n'

MODEL10_CODE = '"""CoAtNet inference compatible with Dread Development\'s public knee checkpoint.\n\nArchitecture and geometry credit: Johnathan Wagner / Dread Development.\nSource: https://www.kaggle.com/code/dreaddevelopment/knee-mri-twelve-findings-from-a-single-model\nModel10: fine-spacing checkpoint evaluated with model8 full coverage.\nThis implementation uses only images and public series metadata.\n"""\nimport gc\nimport json\nimport os\nimport time\nfrom pathlib import Path\n\nos.environ[\'HF_HUB_OFFLINE\'] = \'1\'\nos.environ[\'TRANSFORMERS_OFFLINE\'] = \'1\'\n\nimport cv2\nimport numpy as np\nimport pandas as pd\nimport pydicom\nimport timm\nimport torch\nfrom pydicom.pixels import apply_modality_lut\nfrom torch import nn\nfrom torch.nn import functional as F\n\nUID = \'StudyInstanceUID\'\nSLOTS = [(\'Sagittal\', 1, 18), (\'Sagittal\', 0, 14), (\'Coronal\', 1, 12),\n         (\'Coronal\', 0, 8), (\'Axial\', -1, 12)]\nLABELS = [\'ACL\', \'MCL\', \'Medial Meniscus\', \'Lateral Meniscus\', \'Medial OA\',\n          \'Lateral OA\', \'PF OA\', \'Effusion\', \'Synovitis\', "Baker\'s", \'Contusion\', \'Fracture\']\n\n\nclass Classifier(nn.Module):\n    def __init__(self, arch):\n        super().__init__()\n        self.backbone = timm.create_model(arch, pretrained=False, num_classes=0,\n                                          in_chans=3, global_pool=\'avg\')\n        dim = self.backbone.num_features\n        self.norm = nn.LayerNorm(dim)\n        self.att = nn.Sequential(nn.Linear(dim, 256), nn.Tanh(), nn.Dropout(.2), nn.Linear(256, 12))\n        self.clsW = nn.Parameter(torch.zeros(12, dim))\n        self.clsb = nn.Parameter(torch.zeros(12))\n\n    def predict_features(self, features):\n        features = self.norm(features)\n        attention = self.att(features).softmax(dim=1)\n        pooled = torch.einsum(\'bkn,bkf->bnf\', attention, features)\n        return (pooled * self.clsW).sum(-1) + self.clsb\n\n\ndef ordered_files(directory):\n    records = []\n    for path in directory.glob(\'*.dcm\'):\n        header = pydicom.dcmread(path, stop_before_pixels=True)\n        orientation = getattr(header, \'ImageOrientationPatient\', None)\n        position = getattr(header, \'ImagePositionPatient\', None)\n        if orientation is not None and position is not None and len(orientation) == 6:\n            normal = np.cross(np.asarray(orientation[:3], float), np.asarray(orientation[3:], float))\n            order = float(np.dot(np.asarray(position, float), normal))\n        else:\n            order = float(getattr(header, \'InstanceNumber\', 0) or 0)\n        spacing = getattr(header, \'PixelSpacing\', None)\n        records.append((order, path, float(spacing[0]) if spacing is not None else .5))\n    records.sort(key=lambda x: x[0])\n    return records\n\n\ndef read_study(uid, rows, series_root):\n    volume = np.zeros((64, 336, 336), dtype=np.uint8)\n    used, offset, failed = set(), 0, 0\n    for plane, fluid, count in SLOTS:\n        candidates = [r for r in rows if r[\'Anatomical_Plane\'] == plane and r[\'SeriesInstanceUID\'] not in used]\n        preferred = [r for r in candidates if int(r[\'Fluid_Sensitive\']) == fluid] if fluid in (0,1) else []\n        chosen = (preferred or candidates)\n        if not chosen:\n            offset += count\n            continue\n        row = chosen[0]; used.add(row[\'SeriesInstanceUID\'])\n        records = ordered_files(series_root / uid / row[\'SeriesInstanceUID\'])\n        if not records:\n            raise FileNotFoundError(\'Declared series has no DICOM files\')\n        n = len(records); lo = int(n * .06); hi = max(lo, int(n * .94)-1)\n        indices = np.rint(np.linspace(lo, hi, count)).astype(int) if n > 1 else np.zeros(count, dtype=int)\n        selected = []\n        for i in indices:\n            _, path, spacing = records[min(i, n-1)]\n            try:\n                ds = pydicom.dcmread(path)\n                array = apply_modality_lut(ds.pixel_array, ds).astype(np.float32)\n                if array.ndim != 2 or not np.isfinite(array).all():\n                    raise ValueError(\'Invalid decoded MRI pixels\')\n                if str(getattr(ds, \'PhotometricInterpretation\', \'\')) == \'MONOCHROME1\':\n                    array = array.max() - array\n                selected.append((array, spacing))\n            except (ValueError, RuntimeError, NotImplementedError):\n                selected.append((None, spacing)); failed += 1\n        valid = [a for a, _ in selected if a is not None]\n        if not valid:\n            raise ValueError(\'No decodable slices in selected series\')\n        low, high = np.percentile(np.concatenate([a.ravel() for a in valid]), [2, 98])\n        median_spacing = float(np.median([r[2] for r in records]))\n        for array, spacing in selected:\n            if array is not None:\n                array = np.clip((array-low)/(high-low+1e-6), 0, 1)\n                spacing = spacing if spacing > 0 else median_spacing\n                h, w = array.shape\n                size = min(int(round(140/max(spacing, 1e-3))), h, w)\n                y, x = (h-size)//2, (w-size)//2\n                crop = cv2.resize(array[y:y+size, x:x+size], (336,336), interpolation=cv2.INTER_AREA)\n                volume[offset] = (crop * 255).astype(np.uint8)\n            offset += 1\n    mask = volume.reshape(64,-1).sum(1) > 0\n    if not mask.any():\n        raise ValueError(\'Study has no usable images\')\n    return volume, mask, failed\n\n\ndef windows(volume, mask, size):\n    valid = np.flatnonzero(mask)\n    if len(valid) < 3:\n        valid = np.arange(3)\n    lo, hi = int(valid.min()), int(valid.max())\n    centers = list(range(lo+1, hi)) or [max(1, min((lo+hi)//2, len(volume)-2))]\n    indices = np.arange(len(centers))\n    slices = np.stack([volume[centers[i]-1:centers[i]+2] for i in indices]).astype(np.float32) / 255\n    images = F.interpolate(torch.from_numpy(slices), size=(size,size), mode=\'bilinear\', align_corners=False)\n    return (images - torch.tensor([.485,.456,.406]).view(1,3,1,1)) / torch.tensor([.229,.224,.225]).view(1,3,1,1)\n\n\n@torch.inference_mode()\ndef predict(model, images, device):\n    encoded = []\n    with torch.autocast(device.type, enabled=device.type==\'cuda\', dtype=torch.float16):\n        for batch in images.split(12):\n            encoded.append(model.backbone(batch.to(device)))\n        logits = model.predict_features(torch.cat(encoded).unsqueeze(0))\n    probabilities = logits.float().sigmoid().cpu().numpy()[0]\n    if not np.isfinite(probabilities).all():\n        raise ValueError(\'Nonfinite model predictions\')\n    return probabilities\n\n\ndef main():\n    started = time.time();torch.set_num_threads(4)\n    torch.backends.cudnn.benchmark = True\n    device = torch.device(\'cuda\' if torch.cuda.is_available() else \'cpu\')\n    print(\'Device:\', device, \'torch:\', torch.__version__, \'timm:\', timm.__version__, flush=True)\n    if device.type == \'cuda\':print(\'GPU:\', torch.cuda.get_device_name(), flush=True)\n    inputs = Path(\'/kaggle/input\')\n    roots = [p for p in [inputs/\'competitions/rsna-knee-abnormality-detection\', inputs/\'rsna-knee-abnormality-detection\']\n             if (p/\'test.csv\').exists()]\n    assert len(roots)==1\n    root = roots[0]\n    filename = \'raptor_ft_coatnet_v9_full.pt\'\n    candidates = [inputs/\'raptor-knee-finespacing\'/filename]\n    candidates += list(inputs.glob(\'datasets/dreaddevelopment/raptor-knee-finespacing/\'+filename))\n    candidates += list(inputs.glob(\'datasets/dreaddevelopment/raptor-knee-finespacing/*/\'+filename))\n    files = [p for p in candidates if p.is_file()]\n    assert len(files)==1, files\n    ck = torch.load(files[0], map_location=\'cpu\', weights_only=True)\n    print(\'Checkpoint metadata:\', {k: v for k, v in ck.items() if isinstance(v, (str, int, float, bool))}, flush=True)\n    assert list(ck.get(\'lab\', LABELS)) == LABELS\n    model = Classifier(ck[\'arch\']);model.load_state_dict(ck[\'model\'], strict=True)\n    size = int(ck[\'res\']);del ck;gc.collect()\n    model = model.to(device).eval()\n    test = pd.read_csv(root/\'test.csv\');series = pd.read_csv(root/\'test_series.csv\')\n    sample = pd.read_csv(root/\'sample_submission.csv\')\n    assert test[UID].is_unique and sample[UID].is_unique\n    groups = {uid: frame.to_dict(\'records\') for uid,frame in series.groupby(UID)}\n    result = []\n    for i, uid in enumerate(test[UID]):\n        volume, mask, failed = read_study(uid, groups[uid], root/\'test_series\')\n        result.append(predict(model, windows(volume, mask, size), device))\n        if failed:print(json.dumps({\'study\':i,\'failed_slices\':failed}),flush=True)\n        if i % 50 == 0 or i+1 == len(test):print(\'Predicted\',i+1,\'/\',len(test),\'seconds\',round(time.time()-started,1),flush=True)\n    frame = pd.DataFrame(result, columns=LABELS);frame.insert(0,UID,test[UID].to_numpy())\n    submission = sample[[UID]].merge(frame,on=UID,validate=\'one_to_one\')[sample.columns]\n    assert len(submission)==len(test) and np.isfinite(submission[LABELS]).all().all()\n    submission.to_csv(\'/kaggle/working/submission.csv\',index=False)\n    print(\'Wrote submission.csv; seconds:\',round(time.time()-started,1),flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n'

def main():
    started = time.time()
    out = Path('/kaggle/working')
    for name, code in [('model10',MODEL10_CODE),('model12',MODEL12_CODE),('model15',MODEL15_CODE)]:
        script = out/f'{name}_component.py'
        script.write_text(code)
        subprocess.run([sys.executable,str(script)],check=True)
        (out/'submission.csv').replace(out/f'{name}_predictions.csv')

    uid = 'StudyInstanceUID'
    a = pd.read_csv(out/'model12_predictions.csv').set_index(uid)
    b = pd.read_csv(out/'model15_predictions.csv').set_index(uid)
    assert a.index.is_unique and b.index.is_unique and set(a.index)==set(b.index)
    assert list(a.columns)==list(b.columns)
    b = b.loc[a.index]
    x,y = a.to_numpy(),b.to_numpy()
    assert np.isfinite(x).all() and np.isfinite(y).all()
    c = pd.read_csv(out/'model10_predictions.csv').set_index(uid)
    assert c.index.is_unique and set(c.index)==set(a.index) and list(c.columns)==list(a.columns)
    z = c.loc[a.index].to_numpy()
    assert np.isfinite(z).all()
    pred = (x+y+z)/3
    assert np.isfinite(pred).all() and ((pred>=0)&(pred<=1)).all()
    frame = pd.DataFrame(pred,index=a.index,columns=a.columns)
    frame.to_csv(out/'submission.csv')
    runtime={'studies':len(a),'elapsed_seconds':time.time()-started,'blend':'equal probabilities: model10, model12, model15'}
    (out/'ensemble_runtime.json').write_text(json.dumps(runtime,indent=2))
    print(json.dumps(runtime),flush=True)


if __name__=='__main__':
    main()
